<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($_POST['action']==='blacklist')db()->prepare('INSERT IGNORE INTO blacklists(type,value,reason) VALUES(?,?,?)')->execute([$_POST['type'],trim($_POST['value']),trim($_POST['reason'])]);elseif($_POST['action']==='remove')db()->prepare('DELETE FROM blacklists WHERE id=?')->execute([(int)$_POST['id']]);header('Location: '.base('admin/security.php'));exit;}$adminTitle='مركز الأمان';$logs=db()->query('SELECT * FROM activity_logs ORDER BY id DESC LIMIT 50')->fetchAll();$black=db()->query('SELECT * FROM blacklists ORDER BY id DESC')->fetchAll();include 'header.php';?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="blacklist"><div><label>النوع</label><select name="type"><option value="ip">IP</option><option value="phone">هاتف</option><option value="device">بصمة جهاز</option></select></div><div><label>القيمة</label><input name="value" required></div><div><label>السبب</label><input name="reason"></div><button class="button red">إضافة للقائمة السوداء</button></form><div class="panel"><h2>القائمة السوداء</h2><table class="table"><?php foreach($black as $b):?><tr><td><?=e($b['type'])?></td><td><?=e($b['value'])?></td><td><?=e($b['reason'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="button red">حذف</button></form></td></tr><?php endforeach;?></table></div><div class="panel"><h2>سجل النشاط</h2><table class="table"><tr><th>الحدث</th><th>التفاصيل</th><th>IP</th><th>الوقت</th></tr><?php foreach($logs as $l):?><tr><td><?=e($l['event_type'])?></td><td><?=e($l['details'])?></td><td><?=e($l['ip_address'])?></td><td><?=e($l['created_at'])?></td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>
